using System;
using UnityEngine;
using UnityEditor;
namespace Exoduser {
 public static class A2RR18Checks {
  public static readonly string[] Plants=new string[0];
  public static string[] ExpectedModels(){var names=new System.Collections.Generic.List<string>(A2RR16Calibration.Names);names.AddRange(A2RR16Calibration.R19Names);names.AddRange(Plants);names.AddRange(new[]{"r3_tree_19","r3_tree_24","r3_prop_10","r3_prop_16","r3_prop_17"});return names.ToArray();}
  public static int VerifyPolicy(){var type=typeof(UnityPort.A2RProps3D);var name=type.GetMethod("FoliageModelName");var height=type.GetMethod("FoliageHeight");var yaw=type.GetMethod("FoliageYaw");if(name==null||height==null||yaw==null)throw new Exception("R18 RED: supplied foliage mapping/height/yaw missing");
   foreach(var plant in Plants){bool fern=plant.StartsWith("fern");var card=new UnityPort.A2RWebAssets.Card{id="r18-seed-"+plant,asset="A2R/C10/Art/"+(fern?"r3_":"r4_")+plant,height=.9f};if((string)name.Invoke(null,new object[]{card})!=plant)throw new Exception("Wrong original-card species "+plant);float h=(float)height.Invoke(null,new object[]{card});if(Mathf.Abs(h-(fern?.54f:.45f))>.0001f)throw new Exception("Wrong foliage height "+plant);card.height=.6f;if(fern&&Mathf.Abs((float)height.Invoke(null,new object[]{card})-.40f)>.0001f)throw new Exception("Small fern must be .40m");for(int i=0;i<113;i++){float y=(float)yaw.Invoke(null,new object[]{"card-"+i});if(y< -25||y>25||y!=(float)yaw.Invoke(null,new object[]{"card-"+i}))throw new Exception("Seeded foliage yaw failed");}}
   var allow=UnityPort.A2RProps3D.ParseAllowedModels(Resources.Load<TextAsset>("A2R/Models3D/allowed-models").text);if(!allow.SetEquals(ExpectedModels()))throw new Exception("R19 allowlist must be PASS11 + near trees6 + foliage7, far0");Debug.Log("A2R_R18_POLICY_PASS species7 height .40/.54/.45 deterministic yaw +/-25 far0");return 0;}
  public static int VerifyImported(){VerifyPolicy();foreach(var name in Plants){var root=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Exoduser/Resources/A2R/Models3D/Prefabs/"+name+".prefab");if(root==null)throw new Exception("Missing foliage prefab "+name);var group=root.GetComponent<LODGroup>();if(group==null||group.GetLODs().Length!=3)throw new Exception("Foliage needs three nonempty LODs "+name);foreach(var lod in group.GetLODs()){if(lod.renderers.Length==0)throw new Exception("Empty foliage LOD "+name);foreach(var r in lod.renderers){var mesh=r.GetComponent<MeshFilter>().sharedMesh;var colors=mesh.colors;if(colors.Length!=mesh.vertexCount)throw new Exception("Missing source wind R/G "+name);bool weighted=false;foreach(var c in colors)weighted|=c.r>.01f;if(!weighted)throw new Exception("No wind weights "+name);var m=r.sharedMaterial;if(!m.IsKeywordEnabled("_SPECULARHIGHLIGHTS_OFF")||!m.IsKeywordEnabled("_ENVIRONMENTREFLECTIONS_OFF"))throw new Exception("Foliage reflection path enabled "+name);}}}Debug.Log("A2R_R18_IMPORT_PASS 7 prefabs, 21 LODs, source vertex wind R/G, reflection OFF");return 0;}
 }
}
